DROP TABLE IF EXISTS `records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `teacher` varchar(255) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `faculty` varchar(255) NOT NULL,
  `op` varchar(255) NOT NULL,
  `group_name` varchar(100) NOT NULL,
  `room` varchar(100) NOT NULL,
  `lesson_type` varchar(100) NOT NULL,
  `format` varchar(100) NOT NULL,
  `topic` text NOT NULL,
  `datetime` datetime NOT NULL,
  `students_plan` int NOT NULL,
  `students_fact` int NOT NULL,
  `attendance` float NOT NULL,
  `academic_year` varchar(20) NOT NULL,
  `ratings` json NOT NULL,
  `score` float NOT NULL,
  `status` varchar(50) NOT NULL,
  `comment` text,
  `created_at` datetime NOT NULL DEFAULT (now()),
  `submitted_by` varchar(255) DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `reviewed_by` varchar(255) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_records_id` (`id`),
  KEY `ix_records_subject` (`subject`),
  KEY `ix_records_op` (`op`),
  KEY `ix_records_teacher` (`teacher`),
  KEY `ix_records_group_name` (`group_name`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

