INSERT INTO `records` VALUES (17,'Мукушев Абзал Базарбекович','Финансовый менеджмент','Факультет экономики и бизнеса','Финансы','ФН-232','2/504','Лекция','в традиционном очном формате','Управление оборотным капиталом предприятия','2026-03-30 07:00:00',22,12,54.5,'2025-2026','{\"1.1\": 10, \"1.2\": 9, \"1.3\": 10, \"1.4\": 7, \"1.5\": 8, \"1.6\": 9, \"1.7\": 10, \"2.1\": 9, \"2.2\": 9, \"2.3\": 10, \"2.4\": 9, \"2.5\": 9, \"2.6\": 9, \"3.1\": 9, \"3.2\": 9, \"3.3\": 9, \"3.4\": 9}',9.06,'submitted','Лекция проводилась с помощью интерактивной доски, со студентами была обратная связь, материал излагался доступно','2026-04-02 08:27:04','safuani_zhanar@kaztbu.edu.kz','2026-04-02 08:27:10',NULL,NULL),(18,'Жаппасова Раушан Еркиновна','Рынок ценных бумаг','Факультет экономики и бизнеса','Финансы','ФН-232','2/504','Лекция','в традиционном очном формате','Корпоративное управление: содержание, принципы и механизмы','2026-03-31 04:00:00',22,12,54.5,'2025-2026','{\"1.1\": 10, \"1.2\": 8, \"1.3\": 7, \"1.4\": 9, \"1.5\": 8, \"1.6\": 7, \"1.7\": 10, \"2.1\": 8, \"2.2\": 8, \"2.3\": 9, \"2.4\": 9, \"2.5\": 9, \"2.6\": 8, \"3.1\": 7, \"3.2\": 8, \"3.3\": 9, \"3.4\": 9}',8.41,'submitted','лекционное занятие ориентировано на выполнение заданий, проведено на уровне \"хорошо\", студенты активно выполняли задания','2026-04-02 08:32:25','safuani_zhanar@kaztbu.edu.kz','2026-04-02 08:32:34',NULL,NULL),(19,'Джангельдина Назгуль Нурлановна','Основы предпринимательской деятельности В РДГБ','Факультет экономики и бизнеса','Ресторанное дело и гостиничный бизнес','РДГБ-232','2/402','Практика','в традиционном очном формате','Решение задачи по расчету показателей эффективности ','2026-04-02 08:00:00',31,18,58.1,'2025-2026','{\"1.1\": 7, \"1.2\": 9, \"1.3\": 9, \"1.4\": 9, \"1.5\": 10, \"1.6\": 8, \"1.7\": 10, \"2.1\": 9, \"2.2\": 9, \"2.3\": 10, \"2.4\": 10, \"2.5\": 10, \"2.6\": 10, \"3.1\": 10, \"3.2\": 10, \"3.3\": 8, \"3.4\": 9}',9.24,'draft','В утвержденном силлабусе не проставлена печать с библиотеки. Тема практического занятия не соответствует с силлабусом, но в утвержденном методическом указаний тема указана правильно с фактическим проведенным занятием, а также не указаны должности составителя силлабуса.  Необходимо внести поправки в силабусе.','2026-04-02 08:37:49','botbayeva_zhanar@kaztbu.edu.kz',NULL,NULL,NULL),(20,'Джангельдина Назгуль Нурлановна','Основы предпринимательской деятельности в РДГБ','Факультет экономики и бизнеса','Ресторанное дело и гостиничный бизнес','РДГБ-232','2/405','Практика','в традиционном очном формате','Решение задач по расчету показателей эффективности ','2026-04-02 08:00:00',31,16,51.6,'2025-2026','{\"1.1\": 7, \"1.2\": 9, \"1.3\": 9, \"1.4\": 9, \"1.5\": 10, \"1.6\": 8, \"1.7\": 10, \"2.1\": 9, \"2.2\": 9, \"2.3\": 10, \"2.4\": 10, \"2.5\": 10, \"2.6\": 10, \"3.1\": 10, \"3.2\": 10, \"3.3\": 8, \"3.4\": 9}',9.24,'draft','В утвержденном силлабусе не проставлена печать с библиотеки. Тема практического занятия не соответствует с силлабусом, но в утвержденном методическом указаний тема указана правильно с фактическим проведенным занятием, а также не указаны должности составителя силлабуса.  Необходимо внести поправки в силлабусе.','2026-04-02 08:49:39','yessirkep_gulmira@kaztbu.edu.kz',NULL,NULL,NULL),(21,'Есенова Гульмира Жексеновна','Финансы','Факультет экономики и бизнеса','Государственное и местное управление','ГМУ-241/2','1/405','Практика','в традиционном очном формате','Финансы и инфляция','2025-12-08 08:48:00',23,20,87,'2025-2026','{\"1.1\": 10, \"1.2\": 8, \"1.3\": 8, \"1.4\": 7, \"1.5\": 9, \"1.6\": 6, \"1.7\": 8, \"2.1\": 8, \"2.2\": 9, \"2.3\": 9, \"2.4\": 8, \"2.5\": 8, \"2.6\": 8, \"3.1\": 9, \"3.2\": 9, \"3.3\": 9, \"3.4\": 7}',8.24,'draft','Занятие проведено на хорошем уровне','2026-04-02 08:51:04','tulegulov_amandos@kaztbu.edu.kz',NULL,NULL,NULL),(22,'Хайруллина Райхан Бурхановна','Физика нефтяного и газового пласта','Факультет Инжиниринга и информационных технологий','Нефтегазовое дело','НГДПН-212','3/406','Лекция','в традиционном очном формате','Мұнай және газ коллекторларындағы судың қалдығы дәріс','2025-12-11 06:00:00',25,25,100,'2025-2026','{\"1.1\": 10, \"1.2\": 8, \"1.3\": 8, \"1.4\": 8, \"1.5\": 9, \"1.6\": 9, \"1.7\": 10, \"2.1\": 9, \"2.2\": 9, \"2.3\": 8, \"2.4\": 9, \"2.5\": 10, \"2.6\": 7, \"3.1\": 7, \"3.2\": 8, \"3.3\": 9, \"3.4\": 9}',8.65,'submitted','Положительные отзывы: Лекция охватывает все ключевые аспекты остаточной воды в коллекторах, включая физико-химические свойства и влияние на добычу нефти и газа. Сложные термины и процессы были объяснены простым языком, с примерами из практики.','2026-04-03 08:50:41','baimbetova_rabiga@kaztbu.edu.kz','2026-04-08 06:18:00',NULL,NULL),(23,'Абишева Галия Сериковна','Промышленная экология','Факультет Инжиниринга и информационных технологий','Экология','Э-232','3/505','Лекция','в традиционном очном формате','Естественные радионуклеиды в окружающей среде','2025-12-12 07:00:00',13,10,76.9,'2025-2026','{\"1.1\": 10, \"1.2\": 8, \"1.3\": 9, \"1.4\": 7, \"1.5\": 7, \"1.6\": 8, \"1.7\": 10, \"2.1\": 8, \"2.2\": 8, \"2.3\": 9, \"2.4\": 8, \"2.5\": 9, \"2.6\": 8, \"3.1\": 8, \"3.2\": 8, \"3.3\": 8, \"3.4\": 9}',8.35,'submitted','Лекция на тему «Естественные радионуклиды в окружающей среде» была информативной и доступной для понимания. В ней подробно раскрывались источники природной радиации, её распространение и влияние на человека. Материал был изложен логично и последовательно, что способствовало лучшему усвоению темы.','2026-04-03 09:06:34','baimbetova_rabiga@kaztbu.edu.kz','2026-04-08 06:17:49',NULL,NULL),(24,'Хамит Айтолкын Жумабаевна','Аналитическая химия','Факультет Инжиниринга и информационных технологий','Химическая технология органических веществ','ХТОВ-241','3/406','Лабораторная','в традиционном очном формате','Судың кермектілігін анықтау','2025-12-04 12:00:00',10,9,90,'2025-2026','{\"1.1\": 10, \"1.2\": 9, \"1.3\": 9, \"1.4\": 9, \"1.5\": 8, \"1.6\": 8, \"1.7\": 10, \"2.1\": 9, \"2.2\": 8, \"2.3\": 9, \"2.4\": 9, \"2.5\": 9, \"2.6\": 9, \"3.1\": 9, \"3.2\": 8, \"3.3\": 8, \"3.4\": 9}',8.82,'submitted','Опыт по определению жёсткости воды был проведён наглядно. В ходе работы были продемонстрированы основные методы выявления содержания солей кальция и магния, а также объяснено их влияние на свойства воды. Практическая часть позволила лучше понять теоретический материал и закрепить полученные знания.','2026-04-03 09:15:03','baimbetova_rabiga@kaztbu.edu.kz','2026-04-08 06:18:20',NULL,NULL),(25,'Агайдарова Асель Амангельдыновна','Урбоэкология','Факультет Инжиниринга и информационных технологий','Экология','Э-231','3/106','Практика','в традиционном очном формате','Қаладағы экоулер бойынша түсінік','2025-12-08 09:00:00',11,7,63.6,'2025-2026','{\"1.1\": 10, \"1.2\": 8, \"1.3\": 9, \"1.4\": 8, \"1.5\": 7, \"1.6\": 8, \"1.7\": 10, \"2.1\": 8, \"2.2\": 8, \"2.3\": 8, \"2.4\": 9, \"2.5\": 9, \"2.6\": 8, \"3.1\": 7, \"3.2\": 7, \"3.3\": 8, \"3.4\": 8}',8.24,'submitted','Практическое занятие по теме «Урбоэкология» было содержательным. В ходе работы были рассмотрены основные экологические проблемы городской среды, такие как загрязнение воздуха, уровень шума и рациональное использование ресурсов. Практическая часть позволила применить теоретические знания на конкретных примерах и лучше понять особенности экологического состояния города.','2026-04-03 09:21:46','baimbetova_rabiga@kaztbu.edu.kz','2026-04-08 06:18:11',NULL,NULL),(28,'Ярдякова Ирина Владимировна','Бизнес-планирование в РДГБ','Факультет экономики и бизнеса','Ресторанное дело и гостиничный бизнес','РДГБ-232','2/412','Лекция','в традиционном очном формате','Оценки рисков и страхование','2026-04-06 05:00:00',30,21,70,'2025-2026','{\"1.1\": 10, \"1.2\": 10, \"1.3\": 10, \"1.4\": 7, \"1.5\": 7, \"1.6\": 9, \"1.7\": 10, \"2.1\": 9, \"2.2\": 8, \"2.3\": 10, \"2.4\": 9, \"2.5\": 10, \"2.6\": 9, \"3.1\": 7, \"3.2\": 7, \"3.3\": 7, \"3.4\": 9}',8.71,'submitted','Необходимо усилить организацию самостоятельной и творческой работы обучающихся, а также активнее внедрять современные цифровые ресурсы и интерактивные методы обучения для повышения практикоориентированности занятия.\nПреподаватель демонстрирует высокий уровень владения учебным материалом, обеспечивая его системность, доступность и полное соответствие силлабусу.','2026-04-07 06:58:35','rystygulova_venera@kaztbu.edu.kz','2026-04-08 05:47:31',NULL,NULL),(29,'Муканова Балжан Шамеровна','Туризмдегі анимациялық қызмет','Факультет экономики и бизнеса','Туризм','ТМ-241/1','404/2','Практика','в традиционном очном формате','Анимациялық қызметті жоспарлау және ұйымдастыру функциялары','2026-03-31 06:41:00',25,15,60,'2025-2026','{\"1.1\": 10, \"1.2\": 9, \"1.3\": 9, \"1.4\": 10, \"1.5\": 9, \"1.6\": 10, \"1.7\": 9, \"2.1\": 9, \"2.2\": 9, \"2.3\": 8, \"2.4\": 9, \"2.5\": 9, \"2.6\": 8, \"3.1\": 10, \"3.2\": 9, \"3.3\": 9, \"3.4\": 10}',9.18,'submitted','Тема урока польностью соотвествует силлабусу, прошла на высоком уровне,  с применением интерактивной доски,','2026-04-07 08:46:31','yessirkep_gulmira@kaztbu.edu.kz','2026-04-07 08:46:38',NULL,NULL),(30,'Тыкежанова Гульмира Менгалиевна','Введение в биотехнологию','Технологический факультет','Биотехнология','БТ-242','3/107','Практика','в традиционном очном формате','Биобезопасность как актуальная проблема 21 века','2025-12-10 09:00:00',19,15,78.9,'2025-2026','{\"1.1\": 10, \"1.2\": 10, \"1.3\": 10, \"1.4\": 9, \"1.5\": 10, \"1.6\": 10, \"1.7\": 10, \"2.1\": 10, \"2.2\": 10, \"2.3\": 10, \"2.4\": 10, \"2.5\": 10, \"2.6\": 10, \"3.1\": 9, \"3.2\": 10, \"3.3\": 10, \"3.4\": 10}',9.88,'submitted','100% вовлеченность обучающихся в процесс практического занятия','2026-04-07 09:04:09','omarov_khylysh@kaztbu.edu.kz','2026-04-07 09:04:54',NULL,NULL),(31,'Агедилова Мереке Туяковна','Ғылыми зерттеу неіздері','Технологический факультет','Технология перерабатывающих производств (по отраслям)','ТППроиз-231','1/406','Практика','в традиционном очном формате','Тамақ өнеркәсібіндей ғылыми зерттеулердің','2025-12-08 10:0